// The device's display tools against the server's (OpenSpec change
// assistant-generative-ui, tasks 4.1, 4.2): blocks.vectors.json is generated by
// `go test ./internal/assistant -run DeviceBlockVectors -update` from the server's
// checks over the same rows; here the same calls run against this device's rows.
import 'fake-indexeddb/auto'
import { beforeEach, describe, expect, it } from 'vitest'
import { AGENT_EXCLUSIONS_KEY } from '../agentAccess'
import type { AssistantBlock } from '../assistantBlocks'
import { db, setMeta, useDatabase } from '../db'
import { setCurrentUserId } from '../sharing'
import { runDisplay, type DisplayTurn } from './blocks'
import vectors from './blocks.vectors.json'

let n = 0
beforeEach(async () => {
  useDatabase(`device-blocks-${Date.now()}-${n++}`)
  await setCurrentUserId(vectors.user)
  const rows = vectors.rows as Record<string, Record<string, unknown>[]>
  await db.projects.bulkPut(rows.project.map((r) => ({ ...r, _clock: {} })) as never)
  await db.sections.bulkPut(rows.section.map((r) => ({ ...r, _clock: {} })) as never)
  await db.tasks.bulkPut(rows.task.map((r) => ({ ...r, _clock: {} })) as never)
  await db.notes.bulkPut(rows.note.map((r) => ({ ...r, _clock: {} })) as never)
  await db.places.bulkPut(rows.place.map((r) => ({ ...r, _clock: {} })) as never)
  await setMeta(AGENT_EXCLUSIONS_KEY, vectors.kept_away)
})

/** A block as the server writes it: empty lists left out. */
const canonical = (b: AssistantBlock) => Object.fromEntries(Object.entries(b).filter(([, v]) => !(Array.isArray(v) && v.length === 0)))

describe('display vectors', () => {
  for (const c of vectors.cases as { name: string; calls: { name: string; args: Record<string, unknown> }[]; blocks: unknown[]; results: Record<string, unknown>[] }[]) {
    it(c.name, async () => {
      const turn: DisplayTurn = { shown: 0 }
      const blocks: unknown[] = []
      const results: Record<string, unknown>[] = []
      for (const call of c.calls) {
        const r = await runDisplay(call.name, call.args, turn, (b) => blocks.push(canonical(b)))
        let res = JSON.parse(r.content) as Record<string, unknown>
        if (res.error === 'invalid_arguments') res = { error: 'invalid_arguments' }
        results.push({ ...res, is_error: r.isError })
      }
      expect(blocks).toEqual(c.blocks)
      expect(results).toEqual(c.results)
    })
  }
})
